ROWS=[[inline_refs(c) for c in row] for row in COPY['rows']]
SPECULATION_CASES=load('speculation-case-analysis.json')
for row,case in zip(ROWS,SPECULATION_CASES):
    row[3]=(f'<b>Present gap — what is missing.</b><p>{case["gap"]}</p>'
      f'<p><b>What happens in the book case.</b> <i>{case["case"]}</i></p>{book_case_figure(case)}<p>{case["description"]}</p>'
      f'<p><b>How this helps this probe.</b> {case["relation"]}</p>'
      f'<p><b>The original sentence.</b></p><q>{e(case["quote"])}</q><p>Dunne & Raby, printed pp. {case["pages"]}. {cite(21)} '
      f'<a href="#excerpt-{case["passage"]}">Read the case and quotation →</a></p>'
      f'<p><b>The future situation to try.</b> {case["world"]}</p>'
      f'<p><b>What the visitor sees and decides.</b> {case["prop"]}</p>'
      f'<p><b>What people weigh up.</b> {case["tension"]}</p>'
      f'<p><b>How this changes our choice.</b> {case["selection"]}</p>'
      f'<p><b>What the case cannot tell us.</b> {case["limit"]}</p>')

DIRECTIONS=load('probe-designs.json')

def preview(d):
    if d['id']=='a':
        return '<div class="live-sketch" role="img" aria-label="Design sketch of a source, fabric layout and two AI responses"><span class="eyebrow">THE INTERACTION</span><div class="sketch-flow"><span>Arrange fabric</span><b>→</b><span>AI responds</span><b>→</b><span>Move a piece</span><b>→</b><span>AI responds again</span></div><div class="sketch-mat"><i></i><i></i><i></i></div><p>Your movement changes the next input.</p><p class="small">Two deliberate snapshots. No typing required.</p></div>'
    return '<div class="artifact artifact-b"><div class="artifact-top">ONE SHARED DETAIL <span>DESIGN SKETCH</span></div><div class="shared-swatch"><span>Same source image</span></div><div class="bubble"><b>Visitor 1 · original</b><p>“It reminds me of a tablecloth at home.”</p></div><div class="translation-line">Optional translation · original kept</div><div class="bubble right"><b>Visitor 2 · real reply</b><p>“Do you mean its colour or its pattern?”</p></div><div class="artifact-note">Reply → clarify → preview a postcard → optional email</div></div>'

def extra_detail(d):
    import re
    text=(ROOT/'content'/('probe-'+d['id']+'.html')).read_text(encoding='utf-8')
    return re.sub(r'\[(\d+)\]',lambda m:cite(int(m.group(1))),text)

def heading(num,title,desc=''):
    return f'<div class="section-heading"><span class="eyebrow">{num}</span><h2>{title}</h2>'+ ('<p class="section-intro">'+desc+'</p>' if desc else '')+'</div>'

def direction(d):
    label='A' if d['id']=='a' else 'B'
    theory=''.join(f'<h4>{t}</h4><p>{s} {cite(*r)}</p>' for t,s,r in d['theory'])
    evidence_link='<p><a href="#huayao-to-a">Read what the Huayao study helps us notice and what remains open →</a></p>' if d['id']=='a' else ''
    return f'''<article class="direction direction-{d['id']}" id="probe-{d['id']}">
    <div class="direction-head"><div><span class="route-label">DIRECTION {label} · {e(d['origin'])}</span><h3>{d['title']}</h3><p class="direction-summary">{d['sentence']}</p><div class="chips"><span>{d['focus']}</span><span>{d['time']} · estimate</span><span>Optional AI</span></div></div><span class="direction-letter" aria-hidden="true">{label}</span></div>
    <div class="direction-opening"><div><h4>The question</h4><p class="research-question">{d['rq']}</p><p>{d['purpose']}</p><h4>AI’s role</h4><p>{d['ai']}</p></div><div>{preview(d)}<p class="caption">Illustrative layout. The pattern is a placeholder, not a collection image. Example wording is written for this design, not participant data.</p></div></div>
    <h4 class="subsection-title">What a visitor does</h4><ol class="workflow">{''.join('<li><b>'+t+'</b><p>'+s+'</p></li>' for t,s in d['steps'])}</ol>
    {extra_detail(d)}
    <div class="detail-grid"><details><summary>Theory and the HCI problem</summary>{theory}<h4>What could be new</h4><p>{d['value']} {cite(*d['refs'])}</p>{evidence_link}</details><details><summary>Input, data and analysis</summary><h4>What we record</h4><p>{d['record']}</p><h4>How we read the data</h4><p>{d['analysis']}</p><h4>What would make us revise it</h4><p>{d['checkpoint']}</p></details></div>
    <div class="speculative-use"><span class="eyebrow">THE SPECULATIVE MOMENT</span><h4>A future arrangement to discuss</h4><p class="future-question">{d['future']}</p><p>{d['speculation']}</p><p class="small">Original support: {', '.join('<a href="#excerpt-'+str(n)+'">Passage '+str(n)+'</a>' for n in d['quotenums'])} from Dunne & Raby. {cite(21)}</p></div>
    <details><summary>Set-up, participation and the non-AI route</summary><h4>Smallest working set-up</h4><p>{d['setup']}</p><h4>Lowering entry barriers</h4><p>{d['broad']}</p><h4>If someone declines AI</h4><p>{d['noai']}</p></details>
    </article>'''

def figure(i,alt):
    f=FIGURES[i]
    png=(ROOT/'assets/research'/f['file']).read_bytes()
    width,height=int.from_bytes(png[16:20],'big'),int.from_bytes(png[20:24],'big')
    return f'''<figure class="paper-figure"><a href="assets/research/{f['file']}" target="_blank" rel="noopener"><img src="assets/research/{f['file']}" alt="{e(alt)}" width="{width}" height="{height}"></a><figcaption>{e(f['authors'])} ({f['year']}), original Figure {f['figure']}. {ext(f['doi'],'Paper')} · {ext(f['source_pdf'],'Author PDF')} · {ext(f['license_url'],f['license'])}. Cropped to the figure, with its content unchanged.</figcaption></figure>'''

comparison='<div class="comparison-wrap" tabindex="0" role="region" aria-label="Five-probe comparison table"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in HEADERS)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td data-label="{e(h)}">{c}</td>' for h,c in zip(HEADERS,row))+'</tr>' for row in ROWS)+'</tbody></table></div>'

hero='''<section class="hero" id="overview"><div class="hero-copy"><span class="eyebrow">SECOND-ROUND PROBES · CURRENT DESIGN</span><h1>What feels authentic<br>when AI joins the visit?</h1><p class="hero-lead">Two short activities explore how people connect with heritage objects, express their own experience and understand another visitor.</p><p>A <b>probe</b> gives someone something to try and talk about. Here, “authenticity” is an open question about a real or meaningful connection with an object, its history or other people. We ask visitors what that connection rests on.</p><div class="hero-actions"><a class="button" href="#directions">Explore A & B <span>↓</span></a><a class="text-link" href="#comparison">Compare all five →</a></div><p class="status-line"><span class="status-dot"></span>Research proposals · not yet tested as these new activities</p></div><aside class="reading-guide"><span class="eyebrow">THE IDEA IN 30 SECONDS</span><a href="#probe-a"><span class="mini-letter a">A</span><div><b>Move fabric, see AI respond</b><p>What keeps a link to the source?</p></div><span>↗</span></a><a href="#probe-b"><span class="mini-letter b">B</span><div><b>Explain, translate and reply</b><p>Did my meaning reach you?</p></div><span>↗</span></a><div class="guide-note"><b>One shared foundation</b><p>Named digital heritage material, real participant input, an explicit AI role, and room to disagree or decline AI.</p></div><a class="archive-link" href="archive/initial-five/index.html">Earlier five-probe atlas ↗</a></aside></section>'''

research='''<details class="overall-question"><summary>The wider research question and what “authenticity” means here</summary><h3>How do human–AI interactions shape visitors’ experiences of authenticity in museums and heritage sites?</h3><p>The two supporting questions ask what visitors draw on for authenticity, and how they negotiate different senses of authenticity when interpreting heritage objects with AI. A and B are focused parts of this larger project.</p><p>We do not treat historical accuracy, resemblance, felt connection, personal voice and another person’s understanding as interchangeable. Their relationships are what the activities help us examine. The theories help us decide what to notice. Visitors can give their own reasons and feelings. '''+cite(1,2,3,17)+'''</p></details>'''

iteration=f'''<section id="iteration">{heading('02 / THE ITERATION','Why five became two','This is a traceable design decision, not a ranking of tested outcomes.')}<div class="timeline">{''.join('<article><span>'+n+'</span><h3>'+title+'</h3><p>'+text+'</p></article>' for n,title,text in TIMELINE)}</div><div class="selection-note"><h3>The additional selection criterion</h3><p><b>Make participation possible for more people.</b> Reduce demands on heritage knowledge, language fluency, manual skill, personal devices, friendship pairs and willingness to use AI. This is a design aim to test, not a claim that either activity already works for everyone.</p><p><b>The resulting decision:</b> keep 1 as an introduction, develop 2 as A, pause 3 as a standalone activity, and combine 4 with 5 as B. A take-away supports participation. The research follows actions and reasons in A, and real interpretation and replies in B.</p></div><details><summary>How each piece of feedback changes the design</summary><dl class="feedback"><dt>“Could visitors take something away?”</dt><dd>A can keep a visual record of the two rounds. B adds an optional postcard after the exchange. The record supports a conversation about what happened.</dd><dt>“How can two places see one object?”</dt><dd>B uses the same image, numbered detail and checked fact card in both places. We are studying digital exchange, not moving an original object.</dd><dt>“Can someone choose not to use AI?”</dt><dd>Both routes remain complete without AI. In B, human language support is available when necessary and recorded.</dd><dt>“What role does AI actually play?”</dt><dd>A turns material layouts into visual responses while the visitor is making. B translates during the exchange, then optionally illustrates an approved description. Neither AI role decides whether a heritage object is authentic.</dd><dt>“What about clothing or AI-generated expressions?”</dt><dd>Keep these as later variants. A can optionally compare an arrangement with a sleeve edge. B could add a participant-chosen expression. Full virtual try-on and generated stickers are not necessary for the first study. Emoji interpretation can differ. {cite(18,22)}</dd></dl><p class="small">The 9 October record is a recollected concept-feedback summary, not a transcript. Supervisor guidance is kept as a separate source of design input. No interview recordings or individual participant records are published here.</p></details></section>'''

evidence=f'''<section id="evidence">{heading('04 / RESEARCH AND REAL PRACTICE','What the evidence supports','Original paper figures show the interaction forms. The text explains what the researchers found, how it helps our design and what remains untested.')}<article class="evidence-case" id="huayao-case"><div class="case-heading"><span>01 / MAKING</span><h3>Huayao embroidery: what making reveals, and why it matters for A</h3></div>{figure(0,'Huayao embroiderers beside discarded and selected AI images, finished embroidery and creative goals')}<div class="evidence-reasoning"><h4>The original study and what it could observe</h4><p>The original question concerned forms of creativity when artisans use embodied craft skills with generative AI fine-tuned on their own heritage. Eight Huayao embroiderers worked with the research team. A six-month, four-stage process included shared learning, preparing 152 embroidery images, configuring three generation workflows, co-creating images and embroidering a chosen image. The final in-situ stages took place over eight days. Researchers interviewed people during making, held a focus group and analysed recordings, transcripts and notes using open coding. {cite(12)}</p><p class="process-line">Original study: generated pattern → embroidery → adjustment → explanation of the adjustment</p><h4 id="huayao-findings">What the original research supports</h4><ol class="reasoning-list"><li><b>AI supplied a starting point that people could judge and revise.</b><p>Participants described faster visualisation and new ideas, while continuing to select, discard and modify generated images. This supports treating generation as part of an unfolding practice. It does not establish a measured productivity gain or show that the selected image was already culturally satisfactory.</p></li><li><b>Judgment drew on local knowledge and practical making, not only visual similarity.</b><p>Participants discussed whether animals looked like local animals and seemed to be doing something, whether recognisable motifs were present, and whether density, outlines and composition worked for embroidery. Dianhua explained that she still needed to change a generated image when embroidering it. Their reasons came from local knowledge and making. The study does not give one authenticity rule for everyone.</p></li><li><b>Making exposed judgments that image evaluation alone might miss.</b><p>In the discussion, the authors describe how attention to outlines and shading became clearer through making. They ask whether an image represented Huayao culture in advance, or whether embroiderers brought it into relation with that culture through reconfiguration and reinterpretation. This is an interpretive question arising from the process, not a demonstrated answer that every handmade modification makes an image authentic.</p></li></ol><p class="paper-quote"><b>A participant’s account.</b> Dianhua: “I still have to change it a bit”. <b>The authors’ discussion.</b> “many of the modifications made during the making offer insights”. These are short excerpts. The first concerns modifying an image. The second is the authors’ interpretation of what the process made visible. {cite(12)}</p><p>Figure 5 makes the discarded image, selected image and finished embroidery available for comparison. A visible difference shows that something changed. Its cultural or practical meaning comes from the participant accounts and the researchers’ analysis, not from the photograph alone.</p><p><b>What this does not establish.</b> This is a preliminary CHI extended abstract with eight skilled practitioners and no image-only control condition that would establish the causal contribution of making. Participants’ reports, the researchers’ observations and the authors’ theoretical interpretation should not be treated as the same kind of evidence. The study did not test ordinary museum visitors, AI-written experience cards or an increase in visitor authenticity.</p><h4 id="huayao-to-a">What this suggests for the new A</h4><p>The useful idea is to follow a change through making and ask why it matters. In the Huayao study, experienced embroiderers selected generated images and changed them while stitching. New A lets a museum visitor move simple materials between two AI image responses. The skills, duration and setting differ. This is a reason to try the design, not evidence that it will work.</p><p class="process-line">New A: source detail → layout L1 → generated image G1 → visitor movement → layout L2 → generated image G2 → brief explanation</p><p>Save the actual images and the visitor’s reason. A reopened space might matter because it recalls the chosen object detail. It might simply look nicer. Only the participant’s account can help distinguish these reasons. A short material action does not transfer an embroiderer’s expertise or give new cloth a historical origin.</p><p>Our earlier A used AI to write a making record. That overlapped with B’s focus on personal meaning. The current A uses AI during the making itself. Its unresolved question concerns how a visitor maintains or changes a connection to a source work through actions and responses. The <a href="#a-authenticity">authenticity guide</a> and <a href="#a-art-morph">comparison with Art Morph</a> explain what data would be needed. {cite(1,2,12,22,29,30)}</p><p class="small">Source locations: Method 2 and 2.1, Findings 3.1–3.3, Discussion 4, original Figure 5. Related Huayao papers belong to an associated research programme, not independent replications. ZOMA provides another hybrid-craft precedent, used here at abstract level. {cite(6,7,12)}</p></div></article>
<article class="evidence-case"><div class="case-heading"><span>02 / SOCIAL RECOGNITION</span><h3>The AI Pattern Merchant: a working intervention inside craft relationships</h3></div><div class="figure-pair">{figure(1,'The festival AI Pattern Merchant with a prompting board, sample display, portable printer and online account')}{figure(2,'AI-generated samples placed among existing embroidery patterns at a stall')}</div><div class="two-col"><div><h4>What the research supports</h4><p>The speculative intervention put generation and printing into real relationships of craft, exchange and recognition. A functional prototype can be part of speculation when it opens a different arrangement to discussion. {cite(11)}</p></div><div><h4>What it leaves for A and B</h4><p>A now asks what remains connected to a source work as people and AI remake its appearance. B needs a question about whose interpretations are retained. Ordinary printing or comments alone do not establish speculation. The authors reported attention to the inserted samples but no purchases, so the stall image is not proof of community acceptance.</p></div></div><p class="small">The formal DRS DOI ends in 1403. The reproduced figures come from the author version, whose cover retained an older DOI. We cite the formal metadata.</p></article>
<article class="evidence-case"><div class="case-heading"><span>03 / CROSS-LANGUAGE AGENCY</span><h3>Translation control has benefits and costs</h3></div>{figure(3,'Three machine-translation interfaces showing quality labels, regular post-editing and augmented post-editing')}<div class="two-col"><div><h4>What the research supports</h4><p>In 45 dyads of Chinese new immigrants and English-speaking local residents in the US, post-editing conditions enabled greater exercise of agency, with costs to dyadic communication. The figure shows conditions. The findings come from the paper’s results and discussion. {cite(9)}</p></div><div><h4>What it leaves for B</h4><p>Let people clarify in their own language. Observe the recipient’s actual reply and the sender’s repair. We still need to learn whether this is manageable during a short museum encounter and how it affects the sense that a personal interpretation has been retained.</p></div></div><p class="small">This was everyday information exchange, not a museum or a China–UK comparison. Other research warns that AI suggestions can diminish cultural nuances and that colour-name translation need not preserve perceptual correspondence. These are questions to investigate, not predicted museum effects. {cite(8,10)}</p></article>
<h3 class="subsection-title">What real museums already do</h3><div class="practice-grid"><article><h4>Cleveland Museum of Art</h4><p>Talk to the Art, Art Morph and Extend the Art provide precedents for AI questions, generation and extension. These forms are already in use, so the question must go beyond adding AI. Endless Threads uses a camera and OpenCV, with no generative-AI virtual try-on claim. {cite(22,23,24)}</p></article><article><h4>GIFT and museum souvenirs</h4><p>GIFT links objects and personal messages. Printed data souvenirs already connect a museum visit with a personal record. These projects support the card and interpersonal forms, but were not the proposed generative-AI exchanges. {cite(15,16,26)}</p></article><article><h4>Nasher Museum</h4><p>AI-generated curatorial text is a real precedent. It does not demonstrate that two visitors retain their meanings through translation, reply and clarification. {cite(25)}</p></article></div><details><summary>Other findings that constrain our claims</summary><p>AI co-writing research distinguishes authors’ experiences from readers’ judgments. Heritage narrative research suggests that unfamiliarity can make generated accounts easier to accept. Public attitudes to conversational heritage agents are not deployment effects. {cite(3,4,13)}</p><p>TwistLens studies a specific pre-visit preview task and Gen-Diaolou concerns learning and preservation awareness. Neither licenses a general claim that image editing improves authenticity. HarmonyCut informs structured guidance, without requiring us to copy a complex authoring system. {cite(5,14,19)}</p><p>Research on perceived human versus AI empathy suggests that source attribution can matter in another context. It does not establish an effect in heritage visits. B records wording, translation and image generation separately. A records layouts, actual outputs and reasons separately. {cite(20)}</p></details></section>'''

speculation=f'''<section id="speculation">{heading('05 / SPECULATION','The original words and our design reasoning','Speculation means making an imagined situation clear enough to try and discuss. Here we ask how a future museum could work differently, then use the activity to help people judge that possibility.')}<div class="two-col"><div><h3>For A</h3><p>A possible future museum calls a continually remade digital display the same work. The two actual outputs and a fictional label help visitors discuss what still connects to the source.</p></div><div><h3>For B</h3><p>A possible future museum shows AI translation as the default while originals are filed separately. The participant considers who may authorize that visibility rule. The actual exchange keeps originals and translations together.</p></div></div><p><b>Sequence matters.</b> Complete the ordinary activity first. Clearly introduce the future scenario afterwards. Separate current usability feedback from judgments about the proposed arrangement. If people only discuss convenience and never engage with another arrangement, we cannot claim that the speculative element worked.</p><p class="small">The thirteen passages below combine seven method passages, a selection principle and five case-linked passages. All are original sentences from Anthony Dunne and Fiona Raby’s <i>Speculative Everything</i> (2013). Pages are printed book pages, checked against the supplied pages. Footnote markers are omitted. The meanings and applications are our interpretations. The book does not itself propose either AI museum activity. The book cases help us make design choices. They do not prove that our designs are new or that visitors will respond as expected. The case images below are credited screenshots of the book figures. {cite(21)}</p><p><b>How selection uses speculation.</b> Identify a present default, a changed rule, a material or digital prop, a concrete trade-off and room for a visitor to refuse. All five table rows now make this reasoning explicit. A uses actual image changes to discuss a changing museum work. B uses the exchange and postcard to discuss whose meaning a museum shows. We also consider the research question, participant input and ease of joining.</p><button type="button" id="quote-toggle" class="quiet-button">Open all original passages</button><div class="quote-list">{''.join(f'<details class="quote" id="excerpt-{q["number"]}"><summary><span>Passage {q["number"]} · pp. {q["pages"]}</span>{q["title"]}</summary>{book_case_figure(SPECULATION_CASES[q["number"]-9]) if q["number"]>=9 else ""}<p class="book-case-description">{e(q.get("creator",""))}{". " if q.get("creator") else ""}{e(q.get("case_description",""))}</p><blockquote>{e(q["original"])}</blockquote><p class="quote-source">Dunne & Raby (2013), Chapter {q["chapter"]}, pp. {q["pages"]}. {cite(21)}</p><h4>What this supports</h4><p>{q["meaning"]}</p><h4>Our use and its limit</h4><p>{q["application"]}</p></details>' for q in QUOTES)}</div></section>'''

objects='''<section id="objects">'''+heading('06 / OBJECTS AND THE NEXT STEP','Use digital material from the target venues','Ordinary cloth is an activity material. It is not a heritage object, and the study does not require handling original collections.')+'''<div class="object-layout"><figure class="venue-photo"><img src="https://godshousetower.org.uk/wp-content/uploads/LS-Everyone-Involved-launch-9-scaled.jpg" alt="Installation view of Ian Giles’s Everyone Involved from God’s House Tower’s official exhibition page" loading="lazy" referrerpolicy="no-referrer"><figcaption>Historical exhibition image from God’s House Tower’s official website. Artwork: Ian Giles. Image rights remain with the rights holders. The image is loaded from the source site, not bundled in this repository.</figcaption></figure><div><h3>Preferred textile candidate</h3><p><i>Everyone Involved</i>, Ian Giles, shown at God’s House Tower in 2024, includes wall hangings made with vintage and found fabrics. The venue states that the work would enter Southampton City Art Gallery’s collection after the exhibition. This does not establish GHT ownership or current display. '''+cite(28)+'''</p><p>Select one hanging, a meaningful detail and its contextual information with the venue and artist. Digital image access, use permission and the checked fact card remain to be confirmed. Keep the work’s creative and community context visible.</p><h3>Tudor House & Garden</h3><p>The Leather Jug is an official collection highlight, but it is leather, not a textile. Its clothing-like form can inform a non-textile variant. A strictly textile-led study needs a confirmed textile object or permission to use the GHT-associated digital material at this site with its actual source named. '''+cite(27)+'''</p></div></div><p><b>No verified British–Chinese textile pair has been established at these two venues.</b> B can use one shared object across languages without pretending that nationality determines cultural meaning. The implementation site, exhibition venue and collecting institution must be recorded separately.</p><div class="next-step"><h3>A small first trial</h3><ol><li>Confirm one digital object, the usable image, its context and its fact card.</li><li>Run 4–6 usability walkthroughs of each direction. This is a planning estimate, not a final research sample.</li><li>Check whether people understand the task, contribute specific reasons and can decline AI without being blocked.</li><li>For B, obtain several completed real reply chains. A pending message is not a completed exchange.</li><li>Revise the activities before fixing the final study scale or a comparison design.</li></ol><p>These two self-selected routes help investigate participation and interpretation. They do not establish the causal effect of AI. Detailed theory, data and revision criteria are inside each direction above.</p></div></section>'''

sources='<section id="sources">'+heading('07 / REFERENCES','Sources and reading scope','Numeric references are used throughout. Formal papers, extended abstracts, theory books and official practice records have different evidential roles.')+'<p>Main literature search cut-off: 14 October 2026. Targeted checks for material interaction, Art Morph and the revised A were added on 16 October. Original quotations and figures were checked on 16 October. This is a focused design-oriented evidence synthesis, not a systematic review or a claim that no related work exists. ZOMA and the empathy study are used at abstract level. The Huayao extended abstract is labelled as such. Sources support candidate design choices, not proven outcomes for A or B.</p><ol class="sources">'+''.join(f'<li id="ref-{r["number"]}" value="{r["number"]}">{e(r["title"])} {ext(r["url"],"Source")}<p class="small">{e(r.get("reading_scope",""))}</p></li>' for r in SOURCES)+'</ol><p class="small">Paper figures retain their individual Creative Commons licences, credited below each image. The book quotations and figure screenshots support discussion of the specific cases. Each figure keeps its original caption and credit. Rights remain with the named rights holders. No open licence is claimed for the book figures. No full papers, book chapters, raw interview records, camera data, private drafts or API credentials are included.</p></section>'

