def detail_markdown(s):
    import re
    from html import unescape
    s=re.sub(r'<a class="citation"[^>]*>\[(\d+)\]</a>',r'[\1]',s)
    s=re.sub(r'<img[^>]*src="([^"]+)"[^>]*alt="([^"]*)"[^>]*>',r'![\2](../\1)',s)
    s=re.sub(r'<h[34][^>]*>(.*?)</h[34]>',r'\n\n### \1\n\n',s)
    s=s.replace('</p>','\n\n').replace('</li>','\n').replace('<li>','- ').replace('</article>','\n\n')
    text=unescape(re.sub(r'<[^>]+>','',s))
    text='\n'.join(line.strip() for line in text.splitlines())
    return re.sub(r'\n{3,}', '\n\n', text).strip()

# Plain Markdown notes provide a readable entry inside GitHub as well as the website.
def strip(s):
    import re
    from html import unescape
    s=re.sub(r'<a class="citation"[^>]*>\[(\d+)\]</a>',r'[\1]',s)
    s=re.sub(r'<img[^>]*src="([^"]+)"[^>]*alt="([^"]*)"[^>]*>',r'![\2](../\1)',s)
    s=s.replace('</p>','<br>').replace('<p>','').replace('<b>','**').replace('</b>','**')
    return unescape(re.sub(r'<(?!br\b)[^>]*>','',s))
