    md=f'# Direction {d["letter"]} · {d["title"]}\n\n{d["origin"]}. {d["time"]} is an estimate.\n\n{d["sentence"]}\n\n## Research question\n\n{d["rq"]}\n\n{d["purpose"]}\n\n## Visitor activity\n\n'
    md+='\n\n'.join(f'{i}. **{t}.** {s}' for i,(t,s) in enumerate(d['steps'],1))
