    md+='\n\n## Theory and HCI\n\n'+'\n\n'.join(f'**{t}.** {s} '+ ' '.join(f'[{n}]' for n in rr) for t,s,rr in d['theory'])
    for title,key in [('Speculative scenario','future'),('Where speculation enters','speculation'),('Participant input and data','record'),('Analysis','analysis'),('Candidate contribution','value'),('Revision criterion','checkpoint')]:md+=f'\n\n## {title}\n\n{d[key]}'
