(docs/'SOURCES.md').write_text('# Numeric references\n\nMain search cut-off 14 October 2026. Targeted material-interaction and practice checks added 16 October 2026. Original passages and figures checked 16 October 2026. Focused evidence synthesis, not a systematic review.\n\n'+''.join(f'{r["number"]}. {r["title"]} [Source]({r["url"]})\n\n   Reading scope: {r.get("reading_scope","")}\n\n' for r in SOURCES)+'Paper image licences and original figure numbers are in [the figure credits](../data/figure-credits.json). Figure crops do not change their content. Related Huayao studies are not independent replications. ZOMA and the empathy paper are used at abstract level.\n',encoding='utf-8')
